export function vectorLength(t){return Math.sqrt(Math.pow(t.x,2)+Math.pow(t.y,2))}export function getAngle(t){return Math.atan((t[1].y-t[0].y)/(t[1].x-t[0].x))}export function rotateVector(t,n){return n?{x:Math.cos(n)*t.x-Math.sin(n)*t.y,y:Math.sin(n)*t.x+Math.cos(n)*t.y}:t}function solveLambaSystem(t,n,e){var r=[{n:t[0]-e[0],lambda:n[0]},{n:t[1]-e[1],lambda:n[1]}];return-(r[0].n*n[0]+r[1].n*n[1])/(r[0].lambda*n[0]+r[1].lambda*n[1])}export function perpendicularFoot(t,n){var e=n[0],r=n[1],o={x:r.x-e.x,y:r.y-e.y},a=solveLambaSystem([e.x,e.y],[o.x,o.y],[t.x,t.y]);return{x:e.x+a*o.x,y:e.y+a*o.y}}export function getDistancePointLine(t,n){var e=perpendicularFoot(t,n);return vectorLength({x:e.x-t.x,y:e.y-t.y})}export function getDistancePointPoint(t,n){return vectorLength({x:t.x-n.x,y:t.y-n.y})}